import java.util.*;

public class Ex01ConditionalMatching {
    interface Condition { boolean matches(Ctx ctx); }

    static class Ctx {
        Set<String> classpath = new HashSet<>();
        Set<String> beans = new HashSet<>();
        boolean hasClass(String n) { return classpath.contains(n); }
        boolean hasBean(String n) { return beans.contains(n); }
    }

    static class OnClass implements Condition {
        final String cn;
        OnClass(String c) { cn = c; }
        public boolean matches(Ctx x) { return x.hasClass(cn); }
    }

    static class OnMissingBean implements Condition {
        final String bn;
        OnMissingBean(String b) { bn = b; }
        public boolean matches(Ctx x) { return !x.hasBean(bn); }
    }

    public static void main(String[] args) {
        Ctx ctx = new Ctx();
        ctx.classpath.add("com.zaxxer.hikari.HikariDataSource");

        Condition hasDriver = new OnClass("com.mysql.cj.jdbc.Driver");
        Condition hasPool   = new OnClass("com.zaxxer.hikari.HikariDataSource");
        Condition noUserDs  = new OnMissingBean("dataSource");

        System.out.println("OnClass(mysql driver)     = " + hasDriver.matches(ctx));
        System.out.println("OnClass(hikari pool)      = " + hasPool.matches(ctx));
        System.out.println("OnMissingBean(dataSource) = " + noUserDs.matches(ctx));
        System.out.println("register default DataSource = "
                + (hasPool.matches(ctx) && noUserDs.matches(ctx)));

        ctx.beans.add("dataSource");   // user defines his own DataSource
        System.out.println("--- after user defines dataSource ---");
        System.out.println("OnMissingBean(dataSource) = " + noUserDs.matches(ctx));
        System.out.println("register default DataSource = "
                + (hasPool.matches(ctx) && noUserDs.matches(ctx)));
    }
}
